    elmpocl $p |- ( X e. ( S F T ) -> ( S e. A /\ T e. B ) ) $=
      ( vz co wcel cop cxp wa cdm cv wceq coprab df-mpo eqtri dmoprabss eqsstri
      cmpo dmeqi cfv wrel wfun mpofun funrel ax-mp relelfvdm mpan eleq2s sselid
