      EUNUPWIWEWJUQURSWRXEWFGZVHWMABVQIUIVFXHWMUMVGVFXEWIWFXGUSUTSVAWKWLWMVBURS
      VAWPABVOWBNZKWDABRXICDVCVDABVOWBUHULWHWKWNVBVE $.
  $}

