  $( Introduce new constant symbols. $)
  $c ||r $. $( Ring divisibility relation $)
  $c Unit $. $( Units in a ring $)
  $c Irred $. $( Ring irreducibles $)

  $( Ring divisibility relation. $)
  cdsr $a class ||r $.

  $( Units in a ring. $)
  cui $a class Unit $.

  $( Ring irreducibles. $)
