  relogef $p |- ( A e. RR -> ( log ` ( exp ` A ) ) = A ) $=
    ( cr wcel ce cfv clog cres wceq crp rpefcl reeflog syl relogcl fvresd fvres
    3eqtr4d wb wf1 wa reeff1 f1fveq mpan mpancom mpbid ) ABCZADEZFEZDBGZEZAUHEZ
