  alseuals $p |- ( AE! x ( ph -> ps ) -> AE x ( ph -> ps ) ) $=
    ( wi wal weu wa wex walseu wals euex anim2i df-alseu df-als 3imtr4i ) ABDCE
    ZACFZGPACHZGABCIABCJQRPACKLABCMABCNO $.

